mapper.select:
SELECT "v"."vehicle_id" , "v"."vehicle_name" FROM "vehicles" "v" JOIN "operating_companies" "oc" ON "oc"."del_flag" = 0 AND "oc"."available_flag" = 1
AND "oc"."operating_company_id" = #{session.operatingCompanyId}
AND "oc"."operating_company_id" = "v"."operating_company_id" JOIN "agencies" "a" ON "a"."del_flag" = 0 AND "a"."available_flag" = 1 AND "a"."business_corp_id" = #{session.businessCorpId} AND "a"."business_corp_id" = "oc"."business_corp_id" WHERE "v"."del_flag" = 0 AND "v"."available_flag" = 1

SELECT "vt"."vehicle_tracking_id" , "vt"."created_datetime" , "vt"."latitude_longitude" FROM "vehicles" "v" JOIN "operating_companies" "oc" ON "oc"."del_flag" = 0 AND "oc"."available_flag" = 1
AND "oc"."operating_company_id" = #{session.operatingCompanyId}
AND "oc"."operating_company_id" = "v"."operating_company_id" JOIN "agencies" "a" ON "a"."del_flag" = 0 AND "a"."available_flag" = 1 AND "a"."business_corp_id" = #{session.businessCorpId} AND "a"."business_corp_id" = "oc"."business_corp_id" JOIN "vehicle_tracking" "vt" ON "vt"."del_flag" = 0 AND "vt"."gps_serial" = "v"."gps_serial" WHERE "v"."del_flag" = 0 AND "v"."available_flag" = 1 AND "v"."vehicle_id" = #{vehicleId} ORDER BY "vt"."created_datetime" DESC LIMIT 1;

mapper.sql:
FROM "vehicles" "a" INNER JOIN "operating_companies" "b" ON "b"."available_flag" = 1 AND "b"."del_flag" = 0 AND "b"."operating_company_id" = "a"."operating_company_id" INNER JOIN "agencies" "c" ON "c"."available_flag" = 1 AND "c"."del_flag" = 0 AND "c"."business_corp_id" = "b"."business_corp_id" WHERE "a"."del_flag" = 0 AND "c"."business_corp_id" = #{businessCorpId}
AND "a"."operating_company_id" = #{operatingCompanyId}
AND "a"."vehicle_name" LIKE #{likeVehicleName}
AND "a"."available_flag" = #{availableFlag}
